import json,hashlib,subprocess
from pathlib import Path
root=Path('/var/lib/news-flow/recovery-all-20261123');base=Path('/opt/news-flow/current');p=base/'src/newsFlow/originalReconciliationRead.mjs';old=p.read_bytes()
assert hashlib.sha256(old).hexdigest()=='88e16019b50b41c686e112d2a693503b6d614f4188ef7ee8e301bcd36ff0ff6a'
(root/'before-originalReconciliationRead.mjs').write_bytes(old)
p.write_bytes(b"import {reconcileOriginalArticles} from './baomoiOriginalBranch.mjs';\n\n// A deferred read leaves the durable ES-check marker untouched. The producer\n// can resume on its next normal tick without admitting an unchecked article.\nexport async function reconcileOriginalArticlesWhenAvailable(state,registry,es,{onDeferred=()=>{},limit=50}={}){\n try{await reconcileOriginalArticles(state,registry,es,limit);return true;}\n catch(error){\n  const status=Number(error.statusCode||error.status)||null;\n  const timeout=['ETIMEDOUT','ESOCKETTIMEDOUT'].includes(error.code)||['RequestTimeout','TimeoutError'].includes(error.name)||error.displayName==='RequestTimeout'||status===408||error.name==='StatusCodeError'&&/^Request Timeout after \\d+ms$/.test(error.message);\n  const unavailable=[429,502,503,504].includes(status);\n  const incomplete=error.message==='ORIGINAL_ES_LOOKUP_INCOMPLETE';\n  if(!timeout&&!unavailable&&!incomplete)throw error;\n  onDeferred({event:'original_es_read_deferred',reason:timeout?'ES_READ_TIMEOUT':incomplete?'ES_READ_INCOMPLETE':'ES_READ_UNAVAILABLE',statusCode:status});\n  return false;\n }\n}\n")
(base/'test/news-original-reconciliation-read.test.mjs').write_bytes(b"import test from 'node:test';import assert from 'node:assert/strict';import {DatabaseSync} from 'node:sqlite';\nimport {ThreeFlowState} from '../src/newsFlow/threeFlowState.mjs';\nimport {initializeOriginalBranch,recordOriginalLink,admitOriginalArticles} from '../src/newsFlow/baomoiOriginalBranch.mjs';\nimport {reconcileOriginalArticlesWhenAvailable} from '../src/newsFlow/originalReconciliationRead.mjs';\nfunction fixture(){const state=new ThreeFlowState(new DatabaseSync(':memory:'));initializeOriginalBranch(state.db);const source={domain:'publisher.vn',config:{siteName:'publisher.vn',siteId:'publisher.vn',registrableDomain:'publisher.vn',allowedHosts:['publisher.vn']}};state.configureSites([source]);recordOriginalLink(state,{ok:true,articleId:'123',baomoiUrl:'https://baomoi.com/story-c123.epi',originalUrl:'https://publisher.vn/story-123.html'});return {state,registry:{byHost:()=>source,byUrl:()=>source}};}\ntest('ES timeout defers one read without advancing evidence or admitting an unchecked article; a later successful tick resumes',async()=>{const {state,registry}=fixture(),reports=[];let calls=0;try{const es={search:async()=>{calls++;if(calls===1)throw Object.assign(Error('Request Timeout after 15000ms'),{name:'StatusCodeError',statusCode:408,request:{secret:'must not be reported'}});return {hits:{total:0,hits:[]}};}};assert.equal(await reconcileOriginalArticlesWhenAvailable(state,registry,es,{onDeferred:r=>reports.push(r)}),false);assert.equal(calls,1);assert.equal(state.db.prepare('SELECT es_checked_at FROM baomoi_original_articles').get().es_checked_at,0);assert.equal(admitOriginalArticles(state,registry,100,{requireEsCheck:true}),0);assert.deepEqual(reports,[{event:'original_es_read_deferred',reason:'ES_READ_TIMEOUT',statusCode:408}]);assert.equal(await reconcileOriginalArticlesWhenAvailable(state,registry,es),true);assert.equal(calls,2);assert.equal(admitOriginalArticles(state,registry,100,{requireEsCheck:true}),1);}finally{state.close();}});\ntest('incomplete ES responses and temporary read failures preserve the pending marker',async()=>{for(const failure of [{timed_out:true,hits:{total:0,hits:[]}},...['ETIMEDOUT','ESOCKETTIMEDOUT'].map(code=>Object.assign(Error('unavailable'),{code})),...[429,502,503,504].map(statusCode=>Object.assign(Error('unavailable'),{statusCode}))]){const {state,registry}=fixture();try{const es={search:async()=>{if(failure instanceof Error)throw failure;return failure;}};assert.equal(await reconcileOriginalArticlesWhenAvailable(state,registry,es),false);assert.equal(state.db.prepare('SELECT es_checked_at FROM baomoi_original_articles').get().es_checked_at,0);assert.equal(admitOriginalArticles(state,registry,100,{requireEsCheck:true}),0);}finally{state.close();}}});\ntest('authentication, database, lock and malformed lookup errors remain fatal',async()=>{for(const error of [Object.assign(Error('forbidden'),{statusCode:403}),Object.assign(Error('database'),{code:'ERR_SQLITE_ERROR'}),Error('NEWS_PROCESS_LOCK_LOST'),Error('ORIGINAL_ES_LOOKUP_UNCONFIRMED')]){const {state,registry}=fixture();try{await assert.rejects(reconcileOriginalArticlesWhenAvailable(state,registry,{search:async()=>{throw error;}}),e=>e===error);}finally{state.close();}}});\n\ntest('legacy ES RequestTimeout with Error name and no status defers safely',async()=>{const {state,registry}=fixture(),reports=[];try{const legacy=Object.assign(Error('Request Timeout after 15000ms'),{displayName:'RequestTimeout',status:undefined,body:undefined});assert.equal(legacy.name,'Error');assert.equal(await reconcileOriginalArticlesWhenAvailable(state,registry,{search:async()=>{throw legacy;}},{onDeferred:r=>reports.push(r)}),false);assert.equal(state.db.prepare('SELECT es_checked_at FROM baomoi_original_articles').get().es_checked_at,0);assert.equal(admitOriginalArticles(state,registry,100,{requireEsCheck:true}),0);assert.equal(reports[0].reason,'ES_READ_TIMEOUT');}finally{state.close();}});\n")
r=subprocess.run(['/opt/news-flow/node/bin/node','--test','test/news-original-reconciliation-read.test.mjs','test/news-reviewed-recovery.test.mjs'],cwd=base,capture_output=True,text=True)
(root/'tests-timeout-vps.txt').write_text(r.stdout+r.stderr)
